const notionItems = $input.all();

const existingUrls = notionItems
  .map(item => {
    const props = item.json.properties || {};

    const titleProp = props['Website URL'];
    if (titleProp?.title?.length > 0) {
      return titleProp.title[0].plain_text.toLowerCase().trim().replace(/\/$/, '');
    }

    const urlProp = props['Website'] || props['URL'] || props['Website URL'];
    if (urlProp?.url) {
      return urlProp.url.toLowerCase().trim().replace(/\/$/, '');
    }

    return null;
  })
  .filter(Boolean);

// ---------- SCHEDULE / RUN SLOT ----------
// Adjust the timezone and hour math below to match your own schedule triggers.

let hourNow;

try {
  const scheduleData = $('Daily Schedule - 12-4PM (Dhaka)').first().json;
  hourNow = Number(scheduleData.Hour);
} catch (e) {
  hourNow = Number(
    new Intl.DateTimeFormat('en-US', {
      timeZone: 'Asia/Dhaka', // <-- EDIT: your timezone
      hour: 'numeric',
      hour12: false,
    }).format(new Date())
  );
}

const startHour = 12; // <-- EDIT: hour your first daily run starts
let runSlot = hourNow - startHour;
if (runSlot < 0 || runSlot > 4 || Number.isNaN(runSlot)) {
  runSlot = 0;
}

// ---------- DATE CALCULATION ----------

function getLocalDateParts(date = new Date()) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Dhaka', // <-- EDIT: your timezone
    year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(date);
  const get = type => parts.find(p => p.type === type)?.value;
  return { year: Number(get('year')), month: Number(get('month')), day: Number(get('day')) };
}

const todayParts = getLocalDateParts();
const todayUTC = Date.UTC(todayParts.year, todayParts.month - 1, todayParts.day);
const startDateUTC = Date.UTC(2026, 0, 1); // <-- EDIT: the date you started running this
const dayNumber = Math.max(0, Math.floor((todayUTC - startDateUTC) / 86400000));
const runDate = `${todayParts.year}-${String(todayParts.month).padStart(2, '0')}-${String(todayParts.day).padStart(2, '0')}`;

// ---------- REGIONS ----------
// EDIT: the regions your search rotates through.

const regions = [
  'United States',
  'Canada',
  'United Kingdom',
];

// =====================================================================
// EDIT EVERYTHING BELOW THIS LINE FOR YOUR OWN PRODUCT.
//
// This is where you define who you're looking for. Each "ICP" (ideal
// customer profile) needs:
//   - name / who / pain          -> used in the AI agent's system prompt
//   - qualifying_signals         -> what makes a lead worth verifying
//   - perplexity_prompt          -> a natural-language search instruction
//   - google_queries[]           -> Google search-operator strings; the
//                                    workflow rotates through these day by
//                                    day so you're not hitting the same
//                                    exact query every run
//
// The two examples below are illustrative placeholders only — replace
// them with your own niches, product signals, and search operators.
// =====================================================================

const exampleIcp1Queries = [
  '"local bakery" OR "family bakery" instagram OR facebook -inurl:blog -inurl:docs',
  '"neighborhood cafe" wordpress "menu" filetype:pdf -inurl:blog -inurl:docs',
];

const exampleIcp2Queries = [
  '"independent bookstore" wordpress "events calendar" -inurl:blog -inurl:docs',
  '"local bookshop" "staff picks" newsletter -inurl:blog -inurl:docs',
];

const icpQuerySets = [exampleIcp1Queries, exampleIcp2Queries];
const queryIndex = dayNumber % 2; // <-- EDIT: match the length of your shortest query set

const icps = [
  {
    name: 'EXAMPLE-1 -- Replace With Your Own Niche',
    who: 'Describe the type of organization or business you\'re targeting.',
    pain: 'Describe the specific problem your product solves for them.',
    qualifying_signals: [
      'A fact you can verify with a real HTTP request',
      'Another verifiable, objective signal',
      'A size/scale signal (e.g. "small, single-location")',
    ],
    perplexity_prompt: `List 15 [your target org type] in ${regions[runSlot % regions.length]} that [signal your product needs]. Include their website URLs.`,
    google_operator: `${exampleIcp1Queries[queryIndex % exampleIcp1Queries.length]} "${regions[runSlot % regions.length]}"`,
  },
  {
    name: 'EXAMPLE-2 -- Replace With Your Own Niche',
    who: 'A second example target audience — delete or add more as needed.',
    pain: 'What problem does your product solve for this group specifically?',
    qualifying_signals: [
      'A fact you can verify with a real HTTP request',
      'Another verifiable, objective signal',
    ],
    perplexity_prompt: `List 15 [your second target org type] in ${regions[runSlot % regions.length]} that [signal]. Include their website URLs.`,
    google_operator: `${exampleIcp2Queries[queryIndex % exampleIcp2Queries.length]} "${regions[runSlot % regions.length]}"`,
  },
];

const icpIndex = dayNumber % icps.length;
const todayIcp = icps[icpIndex];
const todayRegion = regions[runSlot % regions.length];
const countryIndex = runSlot % regions.length;

// ---------- OUTPUT ----------

return [
  {
    json: {
      existingUrls,
      existingCount: existingUrls.length,
      todayIcp,
      icpIndex,
      queryIndex,
      todayRegion,
      countryIndex,
      runSlot,
      bdHour: hourNow,
      runDate,
      debug: {
        dayNumber,
        startDateUTC,
        startHour,
        selectedSchedule: `${hourNow}:00`,
        countryFormula: `${runSlot} % ${regions.length}`,
      },
    },
  },
];

const context = $input.first().json;
const { todayIcp, existingUrls, runDate, icpIndex, todayRegion, queryIndex } = context;

// =====================================================================
// EDIT THIS: describe your own product here. This is what the AI agent
// uses to judge whether a lead is a fit, so be specific about what your
// product actually does and who it's for.
// =====================================================================

const YOUR_PRODUCT_NAME = 'Your Product Name';
const YOUR_PRODUCT_DESCRIPTION = `[Your Product Name] is a [type of product] that [what it does, in one sentence].
- [Key feature 1]
- [Key feature 2]
- [Pricing, if relevant to qualifying a lead, e.g. "Starts at $X/mo"]`;

const systemPrompt = `You are a lead discovery agent for ${YOUR_PRODUCT_NAME}.

Your job is to find websites/organizations matching today's ICP using
Perplexity and SerpApi search tools, then return structured lead data.

PRODUCT:
${YOUR_PRODUCT_DESCRIPTION}

TODAY'S ICP:
Name: ${todayIcp.name}
Who: ${todayIcp.who}
Pain: ${todayIcp.pain}
Qualifying signals: ${todayIcp.qualifying_signals.join(', ')}

SIZE RULE (apply, but do not over-exclude):
Prefer small, single-location, volunteer or lightly-staffed organizations.
EXCLUDE only when clearly large: a multi-campus institution, a national
headquarters/denomination office, a Fortune-level or nationally famous
brand. If unsure, INCLUDE it — false positives are fine, we verify
manually downstream.
[EDIT: adjust this rule to match your own product's ideal customer size]

URL RULE (strict — do not change this):
Only use a website_url that appeared literally in a Perplexity result or
a SerpApi search result — copy it exactly as returned. Never construct
or guess a domain from an organization's name. This is the single
biggest defense against the AI hallucinating leads that don't exist.

TODAY'S REGION: ${todayRegion}

VOLUME TARGET (soft): Aim for 15-20 leads across up to 4 search calls.
If fewer qualify after 4 searches, that is acceptable — return whatever
you found. Never apologize, explain, or comment on the count in your
output.

OUTPUT RULES (absolute, no exceptions, regardless of how many leads you found):
- Your entire response must be a single JSON array and nothing else
- The very first character of your response must be [
- The very last character of your response must be ]
- No prose before or after the array, no apologies, no explanations, no markdown, no \`\`\`json fences
- An array with 3 leads formatted correctly is a SUCCESS. An array with 15 leads plus extra text is a FAILURE.
- Only include root domains like example.com or www.example.com
- Do NOT include subdomains like blog.example.com or docs.example.com
- Do NOT include free wordpress.com hosted blogs

REQUIRED JSON SCHEMA PER LEAD:
{
  "website_url": "https://example.com",
  "icp": "${todayIcp.name}",
  "source": "Perplexity" OR "Google Search",
  "org_size": "small/local" OR "large/national" OR "unknown",
  "qualifying_signal_1": "Yes" OR "No" OR "Unknown",
  "qualifying_signal_2": "Yes" OR "No" OR "Unknown",
  "contact_name": "",
  "notes": "One concrete fact about this org, not a generic description"
}
[EDIT: rename qualifying_signal_1/2 to match your own product's actual
qualifying signals — these should mirror what Agent 1.5 checks with a
real HTTP request, not just what the AI guesses]

FILTER RULE: only return leads where org_size is exactly "small/local".
Do not return "large/national" or "unknown" leads.`;

const agentPrompt = `Today is ${runDate}. Running ${todayIcp.name} for region: ${todayRegion}.

STEP 1 — Search with Perplexity
Use perplexity_search with this exact prompt:
"${todayIcp.perplexity_prompt}"

STEP 2 — Search with SerpApi
Use SerpApi Search Tool with this query:
${todayIcp.google_operator}

STEP 3 — Widen if useful (optional, up to 2 more calls)
If you have fewer than 15 qualifying leads, you may run up to 2
additional searches using different cities/states/keywords.

STEP 4 — Output
Write ONLY the JSON array of whatever leads you found — even if fewer
than 15. Starting character [, ending character ]. No other text.`;

return [{
  json: {
    systemPrompt,
    agentPrompt
  }
}];

const agentOutput = $input.first().json.output || 
                    $input.first().json.text || '';

let leads = [];

const jsonMatch = agentOutput.match(/\[\s*\{[\s\S]*?\}\s*\]/);
if (jsonMatch) {
  try {
    leads = JSON.parse(jsonMatch[0]);
  } catch(e) {
    try {
      const cleaned = jsonMatch[0]
        .replace(/[\u201C\u201D]/g, '"')
        .replace(/[\u2018\u2019]/g, "'")
        .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');
      leads = JSON.parse(cleaned);
    } catch(e2) {
      leads = [];
    }
  }
}

const todayIcp = $('Build ICP Context + Skip List').first().json.todayIcp;
const icpIndex = $('Build ICP Context + Skip List').first().json.icpIndex;
const existingUrls = $('Build ICP Context + Skip List').first().json.existingUrls || [];

// Normalize URL for comparison
function normalizeUrl(url) {
  return (url || '').toLowerCase()
    .replace(/https?:\/\/(www\.)?/, '')
    .replace(/\/$/, '')
    .trim();
}

// Build a set of existing normalized URLs for fast lookup
const existingSet = new Set(existingUrls.map(normalizeUrl));

const validLeads = leads
  .filter(lead => lead && lead.website_url)
  .map(lead => ({
    website_url: (lead.website_url || '').trim(),
    icp: lead.icp || todayIcp.name,
    source: lead.source || 'Perplexity',
    org_size: lead.org_size || 'unknown',
    wordpress_confirmed: lead.wordpress_confirmed || 'Unknown',
    has_scanned_pdfs: lead.has_scanned_pdfs || 'Unknown',
    has_private_docs: lead.has_private_docs || 'Unknown',
    notes: lead.notes || '',
    contact_name: lead.contact_name || ''
  }))
  // Backstop: drop any large/national lead even if the agent's own filter missed it
  .filter(lead => lead.org_size !== 'large/national')
  // Deduplicate against all existing URLs in Notion
  .filter(lead => !existingSet.has(normalizeUrl(lead.website_url)))
  // Deduplicate within this batch (in case agent returned same URL twice)
  .filter((lead, index, self) =>
    index === self.findIndex(l => normalizeUrl(l.website_url) === normalizeUrl(lead.website_url))
  )
    // Hard exclude any government domain (.gov, .gov.uk, .gov.au, etc.)
  .filter(lead => !/\.gov(\.[a-z]{2,3})?(\/|$)/i.test(normalizeUrl(lead.website_url)));


if (validLeads.length === 0) {
  return [{ json: { 
    noLeads: true, 
    total: 0, 
    icpName: todayIcp.name,
    icpIndex: icpIndex + 1,
    leads: [] 
  }}];
}

return [{
  json: {
    noLeads: false,
    leads: validLeads,
    total: validLeads.length,
    icpName: todayIcp.name,
    icpIndex: icpIndex + 1
  }
}];

const allSaved = $input.all();
const parseData = $('Parse and Validate Leads').first().json;

return [{
  json: {
    total: parseData.total,
    icpName: parseData.icpName,
    icpIndex: parseData.icpIndex,
    savedCount: allSaved.length,
    runDate: new Date().toISOString().split('T')[0]
  }
}];

